<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){if(get_option('dgs_quiz_marks_schema')==='1')return;global $wpdb;$q=dgs_quiz_tables();$columns=$wpdb->get_col("SHOW COLUMNS FROM {$q['quizzes']}");if(!in_array('sync_marks',$columns,true)&&$wpdb->query("ALTER TABLE {$q['quizzes']} ADD COLUMN sync_marks tinyint unsigned NOT NULL DEFAULT 0")===false)return;update_option('dgs_quiz_marks_schema','1',false);},25);
function dgs_qm_schedule($id){$q=dgs_quiz_row($id);if(!$q||empty($q->sync_marks)||$q->status!=='published')return;if((int)$q->closes_at>time()){if(!wp_next_scheduled('dgs_quiz_marks_sync',[(int)$id]))wp_schedule_single_event((int)$q->closes_at+2,'dgs_quiz_marks_sync',[(int)$id]);return;}$r=dgs_qm_sync($id);if(is_wp_error($r)){update_option('dgs_quiz_marks_error_'.(int)$id,$r->get_error_message(),false);if(!wp_next_scheduled('dgs_quiz_marks_sync',[(int)$id]))wp_schedule_single_event(time()+300,'dgs_quiz_marks_sync',[(int)$id]);}else delete_option('dgs_quiz_marks_error_'.(int)$id);}
add_action('dgs_quiz_marks_sync','dgs_qm_schedule');
function dgs_qm_sync($id){
 if(get_option('dgs_dated_marks')!=='1')return dgs_edu_error('schema','دفتر تاریخ‌دار هنوز آماده نیست.');$q=dgs_quiz_row($id);if(!$q||empty($q->sync_marks)||$q->status!=='published')return 'اتصال خودکار فعال نیست.';
 if(time()<(int)$q->closes_at)return 'نتیجه پس از پایان بازه آزمون وارد دفتر می‌شود.';
 global $wpdb;$qt=dgs_quiz_tables();$pending=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$qt['attempts']} WHERE quiz_id=%d AND submitted_at=0 AND deadline<=%d",$id,time()));foreach($pending as $a){$done=dgs_quiz_finish($q,$a);if(is_wp_error($done))return $done;}
 return dgs_mg_locked(function()use($q,$id){global $wpdb;$qt=dgs_quiz_tables();$t=dgs_mg_tables();$date=wp_date('Y-m-d',(int)$q->opens_at);$period=substr(dgs_att_jdate($date),0,7);if(!dgs_grade_period($period,$q->school_year))return dgs_edu_error('period','ماه آزمون با سال تحصیلی سازگار نیست.');$ctx=['year'=>$q->school_year,'class_id'=>(int)$q->class_id,'subject_id'=>(int)$q->subject_id,'period'=>$period,'system'=>true];$state=dgs_mg_state($ctx['class_id'],$ctx['subject_id'],$period,$ctx['year'],true);if($state->status==='legacy')return dgs_edu_error('legacy','اتصال آزمون منتظر انتقال نمرات قبلی این ماه توسط مدیریت است.');$attempts=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$qt['attempts']} WHERE quiz_id=%d AND submitted_at>0",$id));$changed=false;
 foreach($attempts as $a){$result=json_decode($a->result,true);if(!is_array($result)||!isset($result['grade']))continue;$score=dgs_mg_number((string)$result['grade'],true);if($score===null)throw new RuntimeException('نمره آزمون معتبر نیست.');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['entries']} WHERE source_attempt=%d",$a->id));if($old&&!empty($old->manual_override))continue;
  if($old&&((int)$old->student_id!==(int)$a->student_id||(int)$old->class_id!==(int)$q->class_id||(int)$old->subject_id!==(int)$q->subject_id))throw new RuntimeException('نتیجه متصل‌شده با کلاس یا درس آزمون تطابق ندارد.');
  $row=['school_year'=>$q->school_year,'class_id'=>$q->class_id,'subject_id'=>$q->subject_id,'student_id'=>$a->student_id,'period'=>$period,'evaluation_date'=>$date,'title'=>$q->title,'kind'=>'grade','amount'=>dgs_mg_decimal($score),'note'=>'ثبت خودکار نتیجه آزمون: '.$q->title,'actor_id'=>$q->teacher_id,'updated_at'=>dgs_mg_utc(),'source_quiz'=>$q->id,'source_attempt'=>$a->id,'deleted'=>0];
  if($old&&$old->amount===$row['amount']&&$old->title===$row['title']&&$old->period===$period&&$old->evaluation_date===$date&&!$old->deleted)continue;
  if($old){$row['revision']=(int)$old->revision+1;$ok=$wpdb->update($t['entries'],$row,['id'=>$old->id]);$entry=$old->id;if($old->period!==$period){$oldctx=$ctx;$oldctx['period']=$old->period;$oldstate=dgs_mg_state($oldctx['class_id'],$oldctx['subject_id'],$oldctx['period'],$oldctx['year'],true);dgs_mg_touch($oldctx,$oldstate);dgs_mg_audit($oldctx,'quiz_move_out',$entry,$old,$row,'تغییر تاریخ آزمون');}}
  else{$row['created_at']=dgs_mg_utc();$ok=$wpdb->insert($t['entries'],$row);$entry=$wpdb->insert_id;}if($ok===false)throw new RuntimeException('انتقال نمره آزمون کامل نشد.');$changed=true;dgs_mg_audit($ctx,$old?'quiz_update':'quiz_import',$entry,$old,$row,'نتیجه نهایی آزمون');
 }if($changed)dgs_mg_touch($ctx,$state);return 'نتایج نهایی به دفتر نمرات متصل شدند؛ افراد شرکت‌نکرده نمره خودکار نمی‌گیرند.';});
}
// Catch pending synchronizations when a manager reviews the quiz. No student result
// is copied before its release time; failed imports remain visible to management.
function dgs_qm_notice($q){if(!$q||!dgs_quiz_manage($q)||empty($q->sync_marks))return '';dgs_qm_schedule($q->id);$error=get_option('dgs_quiz_marks_error_'.(int)$q->id);return '<p class="dgq-banner">'.($error?'اتصال دفتر نمره نیاز به بررسی دارد: '.esc_html($error):'اتصال به دفتر نمره فعال است. ثبت پس از پایان بازه آزمون انجام می‌شود؛ اصلاح دستی مدیریت محفوظ می‌ماند.').'</p>';}
